import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"AI Test Automation | SyncETA","description":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support.","frontmatter":{"title":"AI Test Automation | SyncETA","description":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support.","head":[["meta",{"name":"keywords","content":"Test Automation, Testing Generative AI, Playwright, Selenium, Real-time Quality Feedback, Zero-downtime Testing, AI-based Test Automation, Continuous Testing, QAOps, TestOps, Codeless, Low-Code, Self-healing Test, Self-healing, AI Test Automation, Codeless Automation, QA Automation, Software Testing, Test Scenario Creation, Codeless Test, Natural Language Test, Test Automation Tool, Test Automation Platform, Test Efficiency, Playwright, Selenium, QAOps, TestOps, Shift-Left Testing, Shift-Right Testing"}],["meta",{"property":"og:title","content":"AI Test Automation | SyncETA"}],["meta",{"property":"og:description","content":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}]],"sort":1},"headers":[],"relativePath":"en/synceta/index.md","filePath":"en/synceta/index.md","lastUpdated":1784425729000}`),a={name:`en/synceta/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="🚀-synceta-understand-like-a-human-test-like-a-machine" tabindex="-1">🚀 SyncETA: &quot;Understand like a human, test like a machine&quot; <a class="header-anchor" href="#🚀-synceta-understand-like-a-human-test-like-a-machine" aria-label="Permalink to “🚀 SyncETA: &quot;Understand like a human, test like a machine&quot;”">​</a></h1><p><strong>AI-based Web Browser Action Recording and Automated Test Execution System</strong></p><p>SyncETA is an innovative test automation solution that records web browser-based user actions with <strong>Selenium</strong>, automatically generates natural language-based test cases utilizing <strong>LLMs</strong> (Large Language Models), and automatically executes them through <strong>Playwright MCP</strong>. It aims to maximize the efficiency of QA work and continuously improve software quality.</p><h2 id="view-product-introduction" tabindex="-1"><a href="https://synceta.empasy.com/" target="_blank" rel="noreferrer">View Product Introduction</a> <a class="header-anchor" href="#view-product-introduction" aria-label="Permalink to “View Product Introduction”">​</a></h2><h2 id="💡-problems-synceta-aims-to-solve" tabindex="-1">💡 Problems SyncETA Aims to Solve <a class="header-anchor" href="#💡-problems-synceta-aims-to-solve" aria-label="Permalink to “💡 Problems SyncETA Aims to Solve”">​</a></h2><p>Despite test automation being essential in the existing software development and deployment process, there were the following difficulties:</p><ul><li><strong>High implementation costs and maintenance burden</strong>: Significant QA resources are consumed in implementing and maintaining test automation solutions.</li><li><strong>Manual-centric inefficiency</strong>: Test case writing is human-centric, resulting in low repeatability and reusability, and a high probability of human error.</li><li><strong>Increased regression testing burden</strong>: The burden of repetitive regression testing is exacerbated due to frequent release cycle shortening.</li><li><strong>Development knowledge required</strong>: Accessibility for non-technical users (QA teams) was low because development knowledge was required to write scripts for test automation.</li></ul><p>SyncETA solves these problems, providing an integrated solution where all users, including QA engineers, can easily build test automation, reduce maintenance costs, and maximize the efficiency and quality of regression testing.</p><h2 id="🛠️-synceta-s-core-technologies-and-solutions" tabindex="-1">🛠️ SyncETA&#39;s Core Technologies and Solutions <a class="header-anchor" href="#🛠️-synceta-s-core-technologies-and-solutions" aria-label="Permalink to “🛠️ SyncETA&#39;s Core Technologies and Solutions”">​</a></h2><p>SyncETA solves problems and provides an innovative test automation experience through the following key modules.</p><ol><li><strong>SyncETA Recorder (Selenium-based Browser Action Recording Module)</strong>:</li></ol><ul><li>Captures the actual web browser actions of the user (clicks, inputs, scrolls, page transitions, etc.) in real-time and <strong>automatically generates and saves them as test scenarios in a JSON/YAML-based format</strong>.</li><li>Information such as URL, XPath, Class, ID, etc., is recorded together during recording, and the recorded scenarios can be classified, searched, and version-controlled through the management function.</li><li>Provides a <strong>user-friendly screen</strong> such as inputting the recording web URL and free web browser selection and size setting, so anyone can easily record.</li></ul><ol start="2"><li><strong>TestCase Generator (LLM-based Natural Language Test Case Auto-Generation Module)</strong>:</li></ol><ul><li>The recorded scenario (JSON) is analyzed by a <strong>7B or open-source LLM and converted into a natural language-based Excel test case including Step, Input, Expected Result, etc.</strong></li><li>During this process, context learning about in-house terminology and UI elements, and format customizing according to QA standards are supported.</li><li>It can be provided in the form of reusable templates.</li></ul><ol start="3"><li><strong>Test Executor (Playwright MCP Interlocking Auto Test Execution Module)</strong>:</li></ol><ul><li>For test cases approved by QA, an auto-execution script is generated through Playwright MCP, and <strong>supports parallel test execution in a multi-browser automation environment</strong>. It supports compatibility with various browsers such as Chrome, Firefox, and Edge, and the addition of the Safari browser has also been requested.</li><li><strong>Provides a function for the AI to directly execute Excel test cases created or possessed by QA directly without event recording</strong>, maximizing the flexibility of test execution. The AI analyzes fields such as &#39;Step&#39;, &#39;Input&#39;, and &#39;Expected Result&#39; in the Excel file, performs the action in the browser, and verifies the result.</li><li>Provides an execution result report (pass/fail log, screenshots, etc.), and failed test cases are automatically logged.</li><li>Identification is possible when an error occurs during scenario execution, and provides <strong>user-friendly error messages and diagnostic features such as error record screenshots and providing the recorded screen (video) at the time of the error when clicking the error on the dashboard</strong>.</li></ul><ol start="4"><li><strong>QA Feedback Loop (Quality Improvement Loop Module)</strong>:</li></ol><ul><li>QA engineers can directly review, modify, and evaluate the generated Excel test cases, and the modified data is uploaded to the SyncETA system and reflected in the LLM&#39;s re-training (Fine-tuning or RAG).</li><li>Secures LLM training data based on QA&#39;s modifications and continuously improves test case generation quality through periodic re-training. This increases the reliability of auto-generated test cases and improves test coverage. It is also possible to analyze feedback history by QA and track improvement details.</li></ul><h2 id="✨-synceta-s-key-features-and-characteristics" tabindex="-1">✨ SyncETA&#39;s Key Features and Characteristics <a class="header-anchor" href="#✨-synceta-s-key-features-and-characteristics" aria-label="Permalink to “✨ SyncETA&#39;s Key Features and Characteristics”">​</a></h2><ul><li><strong>Dashboard/Management System</strong>: Provides a dashboard for system monitoring such as scenario registration status, execution status, and error status. You can check the video in the execution history, and it helps with error analysis by providing screenshots of error records and recorded videos of the screen when errors occur. Provides precise reports and analysis, and can provide custom reports tailored to customer requirements.</li><li><strong>Data Set Management Feature</strong>: Inputs and manages data in a tabular format, supporting the addition, modification, and deletion of variables. You can write directly by calling variable values set in the scenario, or automatically generate mockup data using AI and conduct tests with various values.</li><li><strong>Scenario Management and Execution Options</strong>: <ul><li><strong>Record</strong>: The basic unit that records user events and DOM information.</li><li><strong>Scenario</strong>: A core component that implements test scenarios by systematically integrating record information.</li><li><strong>Collection</strong>: A feature that selects multiple scenarios and executes them sequentially, guaranteeing a consistent workflow by flexibly combining various scenarios. It is used when simultaneously executing one scenario across multiple browsers.</li><li><strong>Story</strong>: A feature that freely connects scenarios through a Flow Chart interface and dynamically executes the next scenario based on verification results.</li><li><strong>Dynamic Test Chaining</strong>: Enables flexible testing through sequential scenario execution based on conditions.</li><li>Provides various features to facilitate test management, such as initialization upon re-execution, scenario severity setting, and scenario history filtering.</li></ul></li><li><strong>Screen Verification</strong>: Additional data verification is possible after capturing the screen for each event through AI, and when UI changes are detected, it can automatically process the test as a failure.</li><li><strong>Real-time Communication</strong>: Enables checking real-time event actions and DOM information through socket communication.</li><li><strong>Security and Authentication Processing</strong>: Supports automatic login, cookie and session management, HTTP authentication bypass, VPN/Proxy settings, etc.</li><li><strong>CI/CD Integration</strong>: Seamlessly integrates test automation into existing development/deployment processes by interworking with various external tools/systems such as Jenkins, Git, Azure, DevOps, etc.</li><li><strong>Code/Non-code-based Test Design</strong>: Even users lacking development knowledge can easily build test automation with an intuitive GUI and keyword-based non-code methods, and it also provides a script (JavaScript)-based code method for experts.</li><li><strong>API Test Support</strong>: Provides an all-in-one test platform by supporting not only web tests but also API tests.</li></ul><h2 id="🎯-synceta-s-expected-effects" tabindex="-1">🎯 SyncETA&#39;s Expected Effects <a class="header-anchor" href="#🎯-synceta-s-expected-effects" aria-label="Permalink to “🎯 SyncETA&#39;s Expected Effects”">​</a></h2><p>SyncETA contributes to securing business agility and competitiveness by providing the following innovative effects:</p><ul><li><strong>Reduce test case writing time by 80%</strong>: Drastically shortens test case writing time compared to manual work through Selenium recording and LLM-based automatic generation.</li><li><strong>Streamline QA Resources</strong>: Repetitive testing tasks are automated, increasing QA work efficiency and <strong>reducing QA resources by more than 30%</strong>.</li><li><strong>Improve Test Quality and Reliability</strong>: Through AI-based test case generation and the QA feedback loop, test accuracy and coverage are improved, human errors are prevented, and consistent quality is maintained.</li><li><strong>Fast Release and Time-to-Market</strong>: Shortens the development cycle through regression test automation and accelerates time-to-market with rapid feedback.</li><li><strong>Test Automation without Writing Code</strong>: Users lacking development knowledge can also easily build test automation with an intuitive GUI and keyword-based non-code methods.</li><li><strong>Provide a Flexible Test Environment</strong>: Supports various execution options and customization such as cross-browser compatibility, parallel execution, and dynamic chaining.</li><li><strong>User-friendly Error Identification</strong>: Facilitates error analysis by providing user-friendly error messages when an error occurs, recording screenshots, and providing recorded screens when an error occurs.</li></ul><h2 id="🌐-target-audience-and-deployment-format" tabindex="-1">🌐 Target Audience and Deployment Format <a class="header-anchor" href="#🌐-target-audience-and-deployment-format" aria-label="Permalink to “🌐 Target Audience and Deployment Format”">​</a></h2><p>SyncETA can be deployed as a Docker-based installation (On-premise) or in a Cloud SaaS format, and depending on security requirements, the LLM model can be executed on-premise.</p><ul><li><strong>Target</strong>: SaaS web service QA teams, large commerce platforms, enterprises requiring regression test automation, web application development teams, QA engineering teams, DevOps teams, AI/ML teams, etc.</li></ul><h2 id="🏆-synceta-s-differentiated-strengths" tabindex="-1">🏆 SyncETA&#39;s Differentiated Strengths <a class="header-anchor" href="#🏆-synceta-s-differentiated-strengths" aria-label="Permalink to “🏆 SyncETA&#39;s Differentiated Strengths”">​</a></h2><p>Based on the commercialization potential of rapidly rising open-source LLMs and the explosive demand for QA automation, SyncETA provides a <strong>quality improvement model based on an LLM learning feedback loop</strong> that competing solutions do not have. Furthermore, it emphasizes <strong>&#39;Customization in its DNA&#39;</strong>, which can flexibly adjust and expand test environments and features according to customer&#39;s specific requirements, aiming to become a strategic tool contributing to enterprise digital transformation and strengthening competitiveness.</p><hr>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};